/* ════════════════════════════════════════════════════════════
   Portal Events — Detail data context loader (Phase 5H.1)
   Classic IIFE; loads after detail/fragments.js, before detail.js.
   Fetches Supabase data and derived flags for globalThis.evtOpenDetail().
   ════════════════════════════════════════════════════════════ */

'use strict';

async function evtLoadDetailContext(eventId) {
    const events = window.evtAllEvents || globalThis.evtAllEvents;
    const rsvpMap = window.evtAllRsvps || globalThis.evtAllRsvps;
    const event = events.find(e => e.id === eventId);
    if (!event) return null;

    const rsvp = rsvpMap[eventId];
    const start = new Date(event.start_date);
    const end = event.end_date ? new Date(event.end_date) : null;
    const dateStr = start.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });
    const timeStr = start.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
    const endTimeStr = end ? end.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }) : '';
    const typeColors = (window.EventsConstants && window.EventsConstants.TYPE_COLORS_PORTAL) || {};
    const tc = typeColors[event.event_type] || typeColors.member;
    const isLlc = event.event_type === 'llc';
    const isComp = event.event_type === 'competition';

    const [{ data: rsvps }, { data: guestRsvps }] = await Promise.all([
        supabaseClient
            .from('event_rsvps')
            .select('user_id, status, paid, profiles!event_rsvps_user_id_fkey(id, first_name, last_name, profile_picture_url)')
            .eq('event_id', eventId),
        supabaseClient
            .from('event_guest_rsvps')
            .select('id, guest_name, guest_email, status, paid')
            .eq('event_id', eventId),
    ]);
    const goingList = (rsvps || []).filter((r) => {
        if (typeof globalThis.evtIsCommittedGoing === 'function') {
            return window.evtIsCommittedGoing(event, r);
        }
        if (window.EventsHelpers?.rsvpIsCommittedGoing) {
            return window.EventsHelpers.rsvpIsCommittedGoing(event, r);
        }
        return event.pricing_mode === 'paid'
            ? r.paid === true
            : (r.status === 'going' || r.paid === true);
    });
    const maybeList = (rsvps || []).filter(r => r.status === 'maybe');
    const notGoingList = (rsvps || []).filter(r => r.status === 'not_going');
    const guestGoingList = (guestRsvps || []).filter((g) => {
        if (window.EventsHelpers?.rsvpIsCommittedGoing) {
            return window.EventsHelpers.rsvpIsCommittedGoing(event, g);
        }
        return event.pricing_mode === 'paid'
            ? g.paid === true
            : (g.status === 'going' || g.paid === true);
    });

    const { data: checkins, count: checkinCount } = await supabaseClient
        .from('event_checkins')
        .select('user_id, profiles!event_checkins_user_id_fkey(first_name, last_name, profile_picture_url)', { count: 'exact' })
        .eq('event_id', eventId);

    let costItems = [];
    if (isLlc) {
        const { data: ci } = await supabaseClient
            .from('event_cost_items')
            .select('*')
            .eq('event_id', eventId)
            .order('sort_order', { ascending: true });
        costItems = ci || [];
    }

    let waitlist = [];
    let myWaitlistEntry = null;
    if (isLlc) {
        const { data: wl } = await supabaseClient
            .from('event_waitlist')
            .select('*, profiles:user_id(first_name, last_name)')
            .eq('event_id', eventId)
            .order('position', { ascending: true });
        waitlist = wl || [];
        myWaitlistEntry = waitlist.find(w => w.user_id === globalThis.evtCurrentUser.id);
    }

    let raffleEntryCount = 0;
    let myRaffleEntry = null;
    let raffleWinners = [];
    let myCompetitionEntry = null;
    let competitionPhases = [];
    let myCompVote = null;
    if (isComp) {
        const [{ data: myCompEntry }, { data: phases }, { data: myVote }] = await Promise.all([
            supabaseClient
                .from('competition_entries')
                .select('*')
                .eq('event_id', eventId)
                .eq('user_id', globalThis.evtCurrentUser.id)
                .maybeSingle(),
            supabaseClient
                .from('competition_phases')
                .select('*')
                .eq('event_id', eventId)
                .order('phase_num', { ascending: true }),
            supabaseClient
                .from('competition_votes')
                .select('entry_id')
                .eq('event_id', eventId)
                .eq('voter_id', globalThis.evtCurrentUser.id)
                .maybeSingle(),
        ]);
        myCompetitionEntry = myCompEntry;
        competitionPhases = phases || [];
        myCompVote = myVote;
    }
    if (event.raffle_enabled) {
        const { count: rCount } = await supabaseClient
            .from('event_raffle_entries')
            .select('id', { count: 'exact', head: true })
            .eq('event_id', eventId);
        raffleEntryCount = rCount || 0;
        const { data: myEntry } = await supabaseClient
            .from('event_raffle_entries')
            .select('*')
            .eq('event_id', eventId)
            .eq('user_id', globalThis.evtCurrentUser.id)
            .maybeSingle();
        myRaffleEntry = myEntry;
        const { data: winners } = await supabaseClient
            .from('event_raffle_winners')
            .select('*, profiles:user_id(first_name, last_name, profile_picture_url)')
            .eq('event_id', eventId)
            .order('place', { ascending: true });
        raffleWinners = winners || [];
    }

    const isCreator = event.created_by === globalThis.evtCurrentUser.id;
    const { data: hostRecord } = await supabaseClient
        .from('event_hosts')
        .select('id')
        .eq('event_id', eventId)
        .eq('user_id', globalThis.evtCurrentUser.id)
        .maybeSingle();
    const canManageEvent = isCreator || !!hostRecord || (typeof canManageEvents === 'function' && canManageEvents());
    const canAccessTeamHub = canManageEvent || (typeof canAccessAdminDashboard === 'function' && canAccessAdminDashboard());
    const isHost = canManageEvent;
    const canCreateTeamChat = isCreator || (typeof canManageEvents === 'function' && canManageEvents());

    let creatorProfile = (event.creator && event.creator.id) ? { ...event.creator } : null;
    if (event.created_by) {
        const { data: cp } = await supabaseClient
            .from('profiles')
            .select('id, first_name, last_name, profile_picture_url, displayed_badge, title, bio')
            .eq('id', event.created_by)
            .maybeSingle();
        if (cp) creatorProfile = { ...(creatorProfile || {}), ...cp };
        else if (!creatorProfile) {
            creatorProfile = {
                id: event.created_by,
                first_name: '',
                last_name: '',
                profile_picture_url: null,
                displayed_badge: null,
                title: 'Member',
                bio: null,
            };
        }
    }
    const cpName = creatorProfile ? ([creatorProfile.first_name, creatorProfile.last_name].filter(Boolean).join(' ') || 'Member') : '';
    const cpInitials = creatorProfile ? ((creatorProfile.first_name || '?')[0] + (creatorProfile.last_name || '')[0]).toUpperCase() : '';
    const cpBadge = creatorProfile ? evtBadgeChip(creatorProfile.displayed_badge) : '';
    const cpTitle = creatorProfile ? (creatorProfile.title || 'Member') : '';

    const memberGoing = typeof globalThis.evtIsCommittedGoing === 'function'
        ? window.evtIsCommittedGoing(event, rsvp)
        : (window.EventsHelpers?.rsvpIsCommittedGoing
            ? window.EventsHelpers.rsvpIsCommittedGoing(event, rsvp)
            : (event.pricing_mode === 'paid'
                ? !!(rsvp && rsvp.paid === true)
                : !!(rsvp && (rsvp.status === 'going' || rsvp.paid === true))));
    const hasRsvp = rsvp && (memberGoing || rsvp.status === 'maybe');

    let memberPhone = null;
    let eventSmsRecipient = null;
    const { data: memberProfile } = await supabaseClient
        .from('profiles')
        .select('phone')
        .eq('id', globalThis.evtCurrentUser.id)
        .maybeSingle();
    memberPhone = (memberProfile?.phone || '').trim() || null;
    if (memberPhone) {
        const { data: smsRec } = await supabaseClient
            .from('event_sms_recipients')
            .select('id, opted_in, opted_out_at')
            .eq('event_id', eventId)
            .eq('user_id', globalThis.evtCurrentUser.id)
            .maybeSingle();
        eventSmsRecipient = smsRec;
    }
    const documentsHtml = await evtBuildDocumentsHtml(event, isHost, hasRsvp);
    const mapHtml = evtBuildMapHtml(event, hasRsvp, isHost);
    const competitionHtml = isComp ? await evtBuildCompetitionHtml(event, isHost) : '';
    const scrapbookHtml = await evtBuildScrapbookHtml(event, !!hasRsvp);

    const showTime = !event.gate_time || hasRsvp || isHost;
    const showLocation = !event.gate_location || hasRsvp || isHost;
    const showNotes = !event.gate_notes || hasRsvp || isHost;

    const isClosed = event.status === 'completed' || event.status === 'cancelled';
    const isPast = new Date(event.start_date) < new Date() && event.status !== 'active';
    const deadlinePassed = event.rsvp_deadline && new Date(event.rsvp_deadline) < new Date();
    const entriesClosed = isClosed || isPast || deadlinePassed;
    const rsvpEnabled = event.rsvp_enabled !== false;
    const canRsvp = rsvpEnabled && ['open', 'confirmed', 'active'].includes(event.status) && !entriesClosed;
    const Cap = window.EventsCapacity;
    const occupiedForCap = Cap && typeof Cap.countOccupiedCapacity === 'function'
        ? Cap.countOccupiedCapacity(event, { goingList })
        : goingList.length;
    const eventIsFull = Cap && typeof Cap.eventIsAtCapacity === 'function'
        ? Cap.eventIsAtCapacity(event, occupiedForCap)
        : false;

    let amenityVoteConfig = null;
    let amenityVoteTallies = null;
    if (!isComp && window.EventsAmenityVoting && typeof window.EventsAmenityVoting.normalizeConfig === 'function') {
        amenityVoteConfig = window.EventsAmenityVoting.normalizeConfig(event.amenity_voting);
        if (amenityVoteConfig.enabled) {
            const { data: tallyPayload, error: tallyErr } = await supabaseClient
                .rpc('get_event_amenity_vote_tallies', { p_event_id: eventId });
            if (tallyErr) {
                console.warn('Amenity tallies RPC failed', tallyErr);
            }
            const rawTallies = (tallyPayload && tallyPayload.tallies) || {};
            const mapped = {};
            for (const opt of amenityVoteConfig.options) {
                mapped[opt.id] = Number(rawTallies[opt.id]) || 0;
            }
            for (const [id, n] of Object.entries(rawTallies)) {
                if (!(id in mapped)) mapped[id] = Number(n) || 0;
            }
            amenityVoteTallies = mapped;
        }
    }

    let myPaymentPlan = null;
    let myInstallmentsPaid = null;
    let myInstallmentsTotal = null;
    if (event.pricing_mode === 'paid' && globalThis.evtCurrentUser?.id) {
        const { data: parties } = await supabaseClient
            .from('event_parties')
            .select('id, status')
            .eq('event_id', eventId)
            .eq('payer_user_id', globalThis.evtCurrentUser.id)
            .neq('status', 'cancelled')
            .order('created_at', { ascending: false })
            .limit(1);
        const partyId = parties?.[0]?.id;
        if (partyId) {
            const { data: plan } = await supabaseClient
                .from('event_payment_plans')
                .select('id, party_id, plan_kind, method, status, amount_paid_cents, remaining_cents, total_due_cents, next_debit_at')
                .eq('party_id', partyId)
                .maybeSingle();
            myPaymentPlan = plan || null;
            if (plan?.id) {
                const { data: instRows } = await supabaseClient
                    .from('event_payment_installments')
                    .select('id, status, sequence')
                    .eq('plan_id', plan.id);
                const rows = instRows || [];
                const countable = rows.filter((r) => r.status !== 'cancelled');
                myInstallmentsTotal = countable.length || null;
                myInstallmentsPaid = countable.filter((r) => r.status === 'succeeded').length;
            }
        }
        globalThis.evtMyPaymentPlans = globalThis.evtMyPaymentPlans || {};
        globalThis.evtMyPaymentPlans[eventId] = myPaymentPlan;
    }

    return {
        eventId,
        event,
        rsvp,
        start,
        dateStr,
        timeStr,
        endTimeStr,
        tc,
        isLlc,
        isComp,
        goingList,
        maybeList,
        notGoingList,
        guestGoingList,
        checkins,
        checkinCount,
        costItems,
        waitlist,
        myWaitlistEntry,
        raffleEntryCount,
        myRaffleEntry,
        raffleWinners,
        myCompetitionEntry,
        competitionPhases,
        myCompVote,
        isCreator,
        canManageEvent,
        canAccessTeamHub,
        isHost,
        canCreateTeamChat,
        creatorProfile,
        cpName,
        cpInitials,
        cpBadge,
        cpTitle,
        memberGoing,
        hasRsvp,
        documentsHtml,
        mapHtml,
        competitionHtml,
        scrapbookHtml,
        showTime,
        showLocation,
        showNotes,
        isClosed,
        isPast,
        deadlinePassed,
        entriesClosed,
        rsvpEnabled,
        canRsvp,
        eventIsFull,
        memberPhone,
        eventSmsRecipient,
        amenityVoteConfig,
        amenityVoteTallies,
        myPaymentPlan,
        myInstallmentsPaid,
        myInstallmentsTotal,
    };
}

globalThis.evtLoadDetailContext = evtLoadDetailContext;
export const detailDataApi = {
    loadContext: evtLoadDetailContext,
};

const PortalEvents = globalThis.PortalEvents = globalThis.PortalEvents || {};
PortalEvents.detail = PortalEvents.detail || {};
PortalEvents.detail.data = detailDataApi;
